<?php
namespace OberHub;
final class Frontend {
    public static function boot(): void {
        add_action('init',[self::class,'rewrite']);add_filter('query_vars',fn($v)=>array_merge($v,['oh_lang','oh_path']));
        add_filter('template_include',function($t){return self::is_hub() ? get_stylesheet_directory().'/hub.php' : $t;},99);
        add_action('template_redirect',[self::class,'redirect']);
        add_action('wp_enqueue_scripts',[self::class,'assets']);add_action('wp_head',[self::class,'seo'],1);
        add_filter('pre_get_document_title',fn($t)=>self::is_hub() ? self::title().' · Oberriet Hub' : $t);
        add_shortcode('oberhub',[self::class,'render']);
        add_filter('script_loader_tag',function($tag,$handle){return $handle==='oberhub-app' ? preg_replace('/<script(?:\s+type=[\"\'][^\"\']*[\"\'])?\s*/','<script type="module" ',$tag,1) : $tag;},10,2);
        add_filter('wp_robots',function($r){if (self::is_hub() && (!self::operator_ready() || !self::valid())) { $r['noindex']=true;$r['nofollow']=true;unset($r['max-image-preview']); }return $r;});
        add_filter('robots_txt',function($t){return $t."\nDisallow: /wp-admin/\nDisallow: /wp-json/\nSitemap: ".home_url('/oh-sitemap.xml')."\n";});
    }
    public static function rewrite(): void { add_rewrite_rule('^(de|en|ru|uk)/?(.*)$','index.php?oh_lang=$matches[1]&oh_path=$matches[2]','top');add_rewrite_rule('^oh-sitemap\.xml$','index.php?oh_path=sitemap','top'); }
    public static function lang(): string { $l=get_query_var('oh_lang');return in_array($l,['de','en','ru','uk'],true) ? $l : 'de'; }
    public static function path(): string { return trim((string)get_query_var('oh_path'),'/'); }
    public static function is_hub(): bool { return (bool)get_query_var('oh_lang') || self::path()==='sitemap' || (is_front_page() && self::path()===''); }
    public static function ui(): array { static $u; if (!$u) { $u=json_decode(file_get_contents(OBERHUB_DIR.'/ui.json'),true); }return $u[self::lang()]; }
    public static function t(string $key): string { return self::ui()[$key] ?? $key; }
    public static function url(string $path='',?string $lang=null): string { return home_url('/'.($lang ?: self::lang()).'/'.($path ? trim($path,'/').'/' : '')); }
    public static function title(): string {
        $p=explode('/',self::path()); if (self::path()==='') { return self::t('hero'); }
        if (($p[0] ?? '')==='services' && isset($p[1])) { foreach (records('service') as $s) { if ($s['id']===$p[1]) { return $s['title'][self::lang()]; } } }
        if (in_array($p[0] ?? '',['contacts','organizations'],true) && isset($p[1])) { foreach(records($p[0]==='contacts'?'contact':'organization') as $r) { if($r['id']===$p[1]) { return is_array($r['title']) ? $r['title'][self::lang()] : $r['title']; } } }
        if (($p[0] ?? '')==='places') { return ucfirst($p[1] ?? ''); }
        if (($p[0] ?? '')==='topics') { return self::t($p[1] ?? ''); }
        return self::t($p[0]);
    }
    public static function operator_ready(): bool { $o=get_option('oh_operator',[]); return !empty($o['operator']) && !empty($o['address']) && is_email($o['email'] ?? '') && !empty($o['hosting_provider']) && !empty($o['hosting_country']); }
    public static function valid(): bool {
        $p=explode('/',self::path());if (self::path()==='' || in_array(self::path(),['services','search','calendar','waste','ask','contact','about','sources','privacy','imprint','accessibility','organizations','contacts','faq'],true)) { return true; }
        if (count($p)!==2) { return false; }
        if ($p[0]==='places') { return in_array($p[1],['oberriet','montlingen','kriessern','eichenwies','kobelwald'],true); }
        if ($p[0]==='topics') { return in_array($p[1],['administration','everyday-life','health-social','education-family','jobs-business','culture-leisure'],true); }
        if ($p[0]==='services') { return in_array($p[1],array_column(records('service'),'id'),true); }
        if (in_array($p[0],['contacts','organizations'],true)) { return in_array($p[1],array_column(records($p[0]==='contacts'?'contact':'organization'),'id'),true); } return false;
    }
    public static function redirect(): void {
        if (!self::is_hub()) { return; }
        remove_action('wp_head','rel_canonical');if(class_exists(ImportQueue::class)&&ImportQueue::active()){status_header(503);nocache_headers();header('Retry-After: 300');return;}
        if (self::path()==='sitemap') {
            header('Content-Type: application/xml; charset=utf-8');echo '<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">';
            foreach (['de','en','ru','uk'] as $l) { foreach (array_merge(['','services','organizations','contacts','faq','search','topics/administration','topics/everyday-life','topics/health-social','topics/education-family','topics/jobs-business','topics/culture-leisure','calendar','waste','ask','contact','about','sources','privacy','imprint','accessibility'],array_map(fn($x)=>'places/'.$x,['oberriet','montlingen','kriessern','eichenwies','kobelwald']),array_map(fn($s)=>'services/'.$s['id'],records('service'))) as $p) { echo '<url><loc>'.esc_url(self::url($p,$l)).'</loc></url>'; } }echo '</urlset>';exit;
        }
        if (!self::valid()) { status_header(404);nocache_headers(); }
        else { status_header(200);Analytics::count('page_view',self::lang()); if (self::path()==='waste') { Analytics::count('waste_search'); } }
    }
    public static function assets(): void {
        if (!self::is_hub()) { return; }
        remove_action('wp_head','print_emoji_detection_script',7);remove_action('wp_print_styles','print_emoji_styles');remove_action('wp_footer','wp_print_speculation_rules');
        wp_enqueue_style('oberhub',OBERHUB_URL.'assets/app.css',[], '0.2.1');wp_enqueue_script('oberhub-app',OBERHUB_URL.'assets/app.js',[], '0.2.1',true);
    }
    public static function seo(): void {
        if (!self::is_hub()) { return; }
        $url=self::url(self::path());$description=self::title().' — '.self::t('intro').' '.self::t('independent');
        $sp=explode('/',self::path());if (($sp[0] ?? '')==='services' && isset($sp[1])) { foreach (records('service') as $s) { if ($s['id']===$sp[1]) { $description=$s['description_short'][self::lang()]; } } }
        echo '<meta name="description" content="'.esc_attr($description).'"><link rel="canonical" href="'.esc_url($url).'"><link rel="icon" type="image/svg+xml" href="'.esc_url(OBERHUB_URL.'assets/mark.svg').'">';
        foreach (['de'=>'de-CH','en'=>'en','ru'=>'ru','uk'=>'uk'] as $l=>$tag) { echo '<link rel="alternate" hreflang="'.esc_attr($tag).'" href="'.esc_url(self::url(self::path(),$l)).'">'; }
        echo '<link rel="alternate" hreflang="x-default" href="'.esc_url(self::url(self::path(),'de')).'"><meta property="og:title" content="'.esc_attr(self::title().' · Oberriet Hub').'"><meta property="og:description" content="'.esc_attr($description).'"><meta property="og:url" content="'.esc_url($url).'"><meta property="og:type" content="website">';
        $graph=[['@type'=>'WebSite','@id'=>home_url('/#website'),'name'=>'Oberriet Hub','url'=>home_url('/'),'inLanguage'=>['de-CH','en','ru','uk'],'potentialAction'=>['@type'=>'SearchAction','target'=>['@type'=>'EntryPoint','urlTemplate'=>self::url('search').'?q={search_term_string}'],'query-input'=>'required name=search_term_string']],['@type'=>'Organization','@id'=>home_url('/#organization'),'name'=>'Oberriet Hub','url'=>home_url('/')]];
        $p=explode('/',self::path());$graph[]=['@type'=>'BreadcrumbList','itemListElement'=>[['@type'=>'ListItem','position'=>1,'name'=>self::t('home'),'item'=>self::url()],['@type'=>'ListItem','position'=>2,'name'=>self::title(),'item'=>$url]]];
        if ($p[0]==='places') { $graph[]=['@type'=>'Place','name'=>ucfirst($p[1] ?? ''),'url'=>$url]; }
        if ($p[0]==='services' && isset($p[1])) { foreach (records('service') as $s) { if ($s['id']===$p[1] && ($s['source_trust_level'] ?? '')==='A' && preg_match('/Gemeinde|Einwohneramt|Steueramt|Amt für|Kassieramt|Bauamt|AHV-Zweigstelle|Soziale Dienste|Zivilstandsamt|Grundbuchamt|Betreibungsamt/',$s['authority']) && $s['id']!=='lighting') { $graph[]=['@type'=>'GovernmentService','name'=>$s['title'][self::lang()],'description'=>$s['description_short'][self::lang()],'url'=>$url,'provider'=>['@type'=>'GovernmentOrganization','name'=>$s['authority']],'serviceUrl'=>$s['official_url']]; } } }
        if (self::path()==='calendar' || self::path()==='') { foreach (records('event') as $e) { if (($e['end_date'] ?? $e['date']) < wp_date('Y-m-d')) { continue; }$graph[]=['@type'=>'Event','name'=>$e['title'][self::lang()],'startDate'=>$e['date'],'endDate'=>$e['end_date'] ?? $e['date'],'url'=>$e['source_url'],'location'=>['@type'=>'Place','name'=>$e['location']],'description'=>$e['description'][self::lang()],'eventStatus'=>'https://schema.org/EventScheduled']; } }
        // Static JSON only. No AI or resident text is emitted in structured metadata.
        echo '<script type="application/ld+json">'.wp_json_encode(['@context'=>'https://schema.org','@graph'=>$graph],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_UNESCAPED_UNICODE).'</script>';
    }
    public static function source(array $s): string {
        $source=array_column(records('source'),null,'source_id')[$s['source_id'] ?? ''] ?? [];
        $date=$s['source_checked_at'] ?? $source['last_checked'] ?? '';$needs=($source['review_status'] ?? 'checked')!=='checked' || ($date && strtotime($date.' +'.($source['ttl_days'] ?? 30).' days')<time()) || (self::lang()!=='de' && ($s['translation_status'][self::lang()] ?? '')==='stale');
        return '<div class="provenance"><a href="'.esc_url($s['source_url'] ?? $source['source_url'] ?? '#').'" rel="noopener">'.esc_html(self::t('source')).' ↗</a><span>'.esc_html(self::t('checked').' '.$date).'</span>'.($needs ? '<span class="warning">'.esc_html(self::t('needsreview')).'</span>' : '').'</div>';
    }
    public static function card(array $s): string {
        $l=self::lang();return '<article class="service-card" data-topic="'.esc_attr($s['topic']).'"><div class="eyebrow">'.esc_html(self::t($s['topic'])).'</div><h3><a href="'.esc_url(self::url('services/'.$s['id'])).'">'.esc_html($s['title'][$l]).'</a></h3><p>'.esc_html($s['description_short'][$l]).'</p><div class="card-bottom"><span>'.esc_html($s['authority']).'</span><a class="arrow" aria-label="'.esc_attr(self::t('details').' — '.$s['title'][$l]).'" href="'.esc_url(self::url('services/'.$s['id'])).'">↗</a></div>'.self::source($s).'</article>';
    }
    public static function select(string $id,string $label,array $values): string { $h='<label class="field" for="'.esc_attr($id).'">'.esc_html($label).'<select id="'.esc_attr($id).'">'; foreach ($values as $v=>$name) { $h.='<option value="'.esc_attr($v).'">'.esc_html($name).'</option>'; }return $h.'</select></label>'; }
    public static function localities(): array { return ['all'=>self::t('all'),'oberriet'=>'Oberriet','montlingen'=>'Montlingen','kriessern'=>'Kriessern','eichenwies'=>'Eichenwies','kobelwald'=>'Kobelwald']; }
    public static function searchform(): string { return '<form id="search-form" role="search"><label class="sr-only" for="query">'.esc_html(self::t('search')).'</label><div class="searchbox"><span aria-hidden="true">⌕</span><input type="search" id="query" autocomplete="off" maxlength="300" placeholder="'.esc_attr(self::t('placeholder')).'" aria-controls="search-results"><button type="submit">'.esc_html(self::t('search')).' <span aria-hidden="true">→</span></button></div></form><div id="search-results" class="search-results" aria-live="polite"></div>'; }
