        <main id="main" class="wrap" tabindex="-1">
        <?php if (!$valid) { ?><section class="pagehead"><h1><?php echo esc_html($u['notfound']); ?></h1><a class="button" href="<?php echo esc_url(self::url()); ?>"><?php echo esc_html($u['home']); ?></a></section><?php } else {
