            case 'faq':echo '<div class="prose">';foreach(self::slice($d['faqs'] ?? []) as $r){echo '<details><summary>'.esc_html(is_array($r['title'])?$r['title'][$l]:$r['title']).'</summary><p>'.esc_html($r['answer'][$l] ?? $r['description_short'][$l] ?? '').'</p>'.self::source($r).'</details>';}echo '</div>'.self::pagination(count($d['faqs'] ?? []));break;
            case 'contact':echo '<div class="cards">';foreach(self::slice($d['contacts']) as $c) { ?><article class="service-card"><h2><a href="<?php echo esc_url(self::url('contacts/'.$c['id'])); ?>"><?php echo esc_html($c['title']); ?></a></h2><p><?php echo esc_html($c['phone']); ?></p><?php if(is_email($c['email'])) { ?><a href="<?php echo esc_url('mailto:'.$c['email']); ?>"><?php echo esc_html($c['email']); ?></a><?php } ?><p><a href="<?php echo esc_url($c['official_url']); ?>"><?php echo esc_html($u['official']); ?> ↗</a></p><?php echo self::source($c); ?></article><?php }echo '</div>';break;
            case 'sources':echo '<div class="prose"><p>'.esc_html($u['quality']).'</p><p>'.esc_html($u['trustlevels']).'</p></div><div class="source-table">';foreach(self::slice($d['sources']) as $s) { ?><article><span class="badge"><?php echo esc_html($s['trust_level']); ?></span><div><h2><a href="<?php echo esc_url($s['source_url']); ?>"><?php echo esc_html($s['authority']); ?> ↗</a></h2><p><?php echo esc_html($s['source_domain'].' · '.$u['checked'].' '.$s['last_checked']); ?></p><small><?php echo esc_html($s['review_status']); ?></small></div></article><?php }echo '</div>'.self::pagination(count($d['sources']));break;
            default:echo self::legal($active);break;
        }
        } }
        ?><section class="trust-strip"><strong><?php echo esc_html($u['quality']); ?></strong><span><?php echo esc_html($u['free']); ?></span><a href="<?php echo esc_url(self::url('sources')); ?>"><?php echo esc_html($u['sources']); ?> →</a></section></main><footer><div class="wrap footer-main"><a class="brand" href="<?php echo esc_url(self::url()); ?>">oberriet<span class="brand-light">hub</span></a><p><?php echo esc_html($u['disclaimer']); ?></p><nav><?php foreach(['about','contact','sources','privacy','imprint','accessibility'] as $p) { ?><a href="<?php echo esc_url(self::url($p)); ?>"><?php echo esc_html($u[$p]); ?></a><?php } ?></nav><p class="emergency"><?php echo esc_html($u['emergency']); ?>: <a href="tel:112">112</a> · <?php echo esc_html($u['police']); ?> <a href="tel:117">117</a> · <?php echo esc_html($u['fire']); ?> <a href="tel:118">118</a> · <?php echo esc_html($u['ambulance']); ?> <a href="tel:144">144</a> · Tox <a href="tel:145">145</a> <a href="https://www.hallo.sg.ch/de/beratung-kontakte/notfaelle.html"><?php echo esc_html($u['source']); ?> ↗</a></p></div></footer></div><?php return ob_get_clean();
    }
    public static function slice(array $rows): array { $page=max(1,min(10000,absint($_GET['listing_page'] ?? 1)));return array_slice($rows,($page-1)*24,24); }
    public static function pagination(int $count): string { $page=max(1,absint($_GET['listing_page'] ?? 1));$pages=(int)ceil($count/24);if($pages<=1)return ''; $h='<nav class="pagination" aria-label="'.esc_attr(self::t('pages')).'">';if($page>1)$h.='<a class="button secondary" href="'.esc_url(add_query_arg('listing_page',$page-1,self::url(self::path()))).'">← '.esc_html(self::t('previous')).'</a>'; $h.='<span>'.(int)$page.' / '.$pages.'</span>';if($page<$pages)$h.='<a class="button secondary" href="'.esc_url(add_query_arg('listing_page',$page+1,self::url(self::path()))).'">'.esc_html(self::t('next')).' →</a>';return $h.'</nav>'; }
    public static function entity_card(array $r,string $kind): string { $l=self::lang();$title=is_array($r['title'] ?? null)?$r['title'][$l]:($r['title'] ?? $r['id']);$h='<article class="service-card"><h2><a href="'.esc_url(self::url($kind.'/'.$r['id'])).'">'.esc_html($title).'</a></h2>';if(!empty($r['description_short'][$l]))$h.='<p>'.esc_html($r['description_short'][$l]).'</p>';if(!empty($r['address']))$h.='<p>'.esc_html(is_array($r['address'])?implode(', ',$r['address']):$r['address']).'</p>';if(!empty($r['phone']))$h.='<p><a href="'.esc_url('tel:'.preg_replace('/[^+0-9]/','',$r['phone'])).'">'.esc_html($r['phone']).'</a></p>';if(is_email($r['email'] ?? ''))$h.='<p><a href="'.esc_url('mailto:'.$r['email']).'">'.esc_html($r['email']).'</a></p>';if(!empty($r['official_url']))$h.='<a href="'.esc_url($r['official_url']).'">'.esc_html(self::t('official')).' ↗</a>';return $h.self::source($r).'</article>'; }
    public static function detail_extra(array $s,array $d): string { $l=self::lang();$h='';foreach(['steps'=>'steps','documents'=>'documents','processing_time'=>'processingtime','eligibility'=>'eligibility'] as $key=>$label){$v=$s[$key] ?? null;if(!$v)continue;if(is_array($v)&&isset($v[$l]))$v=$v[$l];$h.='<h2>'.esc_html(self::t($label)).'</h2>';if(is_array($v)){$h.='<ol>';foreach($v as $item){$h.='<li>'.esc_html(is_scalar($item)?(string)$item:'').'</li>';}$h.='</ol>';}else{$h.='<p>'.esc_html((string)$v).'</p>';}}$related=array_filter($d['services'],fn($r)=>$r['id']!==$s['id']&&(in_array($r['id'],$s['related_services'] ?? [],true)||$r['topic']===$s['topic']));if($related){$h.='<h2>'.esc_html(self::t('related')).'</h2><ul>';foreach(array_slice(array_values($related),0,5) as $r){$h.='<li><a href="'.esc_url(self::url('services/'.$r['id'])).'">'.esc_html($r['title'][$l]).'</a></li>';}$h.='</ul>';}return $h; }
    public static function legal(string $page): string {
        $content=json_decode(file_get_contents(OBERHUB_DIR.'/legal.json'),true);$l=self::lang();$o=get_option('oh_operator',[]);$h='<article class="prose">';
        foreach (($content[$page][$l] ?? []) as $text) { $h.='<p>'.esc_html($text).'</p>'; }
        if ($page==='imprint' || $page==='privacy') {
            if (self::operator_ready()) { $h.='<p>'.esc_html(implode(' · ',array_filter([$o['operator'],$o['organization'] ?? '',$o['responsible_person'] ?? '',$o['address'],$o['email'],$o['phone'] ?? '']))).'</p>'; }
            else { $h.='<p class="warning">'.esc_html($content['operator_missing'][$l]).'</p>'; }
        }
        if ($page==='privacy') { if (!empty($o['hosting_provider'])) { $h.='<p>Hosting: '.esc_html($o['hosting_provider'].' · '.$o['hosting_country']).'</p>'; }$h.='<p><a href="https://www.fedlex.admin.ch/eli/cc/2022/491/de">DSG SR 235.1 ↗</a> · <a href="https://www.edoeb.admin.ch/de/das-neue-datenschutzgesetz-aus-sicht-des-edob">EDÖB ↗</a></p>'; }
        if ($page==='imprint') { $h.='<p><a href="https://www.fedlex.admin.ch/eli/cc/2015/613/de">WSchG SR 232.21 ↗</a> · <a href="https://www.ige.ch/de/etwas-schuetzen/marken/vor-der-anmeldung/schutzvoraussetzungen/eintragungshindernisse/geschuetzte-oeffentliche-zeichen">IGE ↗</a></p>'; }
        return $h.'</article>';
    }
}
